"""Generate a review appendix from audit/coverage evidence; never edits theme files."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'qa/phase4'
graph = json.loads((OUT / 'reference-graph.json').read_text())
coverage = json.loads((OUT / 'coverage.json').read_text())
seen = set(coverage['observedClassTokens'])
lines = ['# Cleanup candidate appendix — no removal approved', '',
         'Generated by `python3 qa/phase4/candidates.py`. Read [CLEANUP-REPORT.md](../../CLEANUP-REPORT.md) first.', '',
         'CSS rows identify class-specific selector branches for review, not permission to delete a whole rule or file. Shared selector lists must preserve their active branches. Local absence cannot prove native/editor absence.', '',
         '## CSS token scan', '',
         '| ID | Path and first occurrence | Class | Evidence / reason | Confidence unused | Risk / decision |',
         '|---|---|---|---|---|---|']
protected = {
    'atelier-header-section': ('Schema-generated section wrapper; literal markup scan misses schema metadata.', 'False positive', 'High: keep header wrapper styling.'),
    'header-menu--mobile': ('Built by header-menu-- plus mode in navigation-tree.liquid.', 'False positive', 'High: keep mobile menu styling.'),
    'local-preview-notice': ('Injected by seed/preview-liquid.mjs; outside native runtime scan.', 'False positive', 'High: keep local preview marker on MUST-NOT-LOSE list.'),
}
for i, item in enumerate(sorted(graph['cssClassesWithoutExactRuntimeToken'], key=lambda x: (x['source'], x['className'])), 1):
    source, name = item['source'], item['className']
    text = (ROOT / source).read_text()
    line = text[:text.index('.' + name)].count('\n') + 1
    if name in protected:
        reason, confidence, risk = protected[name]
    elif name in seen:
        reason, confidence, risk = 'Observed in local DOM; static scan missed its construction.', 'False positive', 'Keep; inspect dynamic source.'
    else:
        reason = 'No exact class token outside native CSS; not observed in sampled local DOM.'
        confidence = 'Medium'
        risk = 'Medium: merchant rich text/Custom Liquid or native states may use it; defer removal.'
        if name in ('h4', 'hairline-top', 'section-spacing-top', 'section-spacing-bottom'):
            risk = 'High: generic utility may be used in merchant content; keep pending content review.'
    lines.append(f'| CSS-{i:03} | [{source}:{line}](../../{source}#L{line}) | `{name}` | {reason} | {confidence} | {risk} |')
lines.extend(['', '## Locale keys without literal references', '',
              'The graph checks translation calls and `t:` schema references. All entries below are in `locales/en.default.json`; none is approved for removal. Plural leaves need parent-key review. No other locale files are present.', '',
              '| ID | Path / key | Why it looks unused | Confidence unused | Risk / decision |',
              '|---|---|---|---|---|'])
for i, item in enumerate([v for v in graph['localeKeys'] if not v['literalReferences']], 1):
    risk = 'Medium: future/conditional translation or content use; review individually.'
    if item['key'].endswith(('.one', '.other')):
        risk = 'High: plural parent calls can consume leaves; inspect parent before considering removal.'
    lines.append(f'| LOC-{i:03} | `{item["source"]}` → `{item["key"]}` | No literal translation call or schema t: reference found. | Medium | {risk} |')
lines.extend(['', '## Protected addable sections', '',
              'No incoming saved-template reference does not make an addable section dead. Keep all 16 preset sections:', ''])
lines.extend('- `' + name + '`' for name in sorted(graph['protectedPresetSections']))
lines.extend(['', 'All required templates, dynamically fetched helpers, and MUST-NOT-LOSE components are also protected. See the main report for image candidates, duplicate templates and demo-content decisions.', ''])
(OUT / 'CANDIDATES.md').write_text('\n'.join(lines))
print('Wrote CSS and locale review appendix; no theme edits.')
